export function getAllStaticLandscapingSlugs(): string[] {
  const slugs: string[] = [];
  Object.values(LANDSCAPING_STATIC_DATA).forEach((item) => {
    slugs.push(item.slug);
    if (item.aliases) {
      slugs.push(...item.aliases);
    }
  });
  return Array.from(new Set(slugs));
}

export function getLandscapingStaticDataBySlug(
  slug: string
): LandscapingStaticDetail | undefined {
  if (!slug) return undefined;
  const normalized = slug.toLowerCase().trim();

  // 1. Direct match by key
  if (LANDSCAPING_STATIC_DATA[normalized]) {
    return LANDSCAPING_STATIC_DATA[normalized];
  }

  // 2. Match by slug field or aliases
  return Object.values(LANDSCAPING_STATIC_DATA).find(
    (item) =>
      item.slug.toLowerCase() === normalized ||
      item.aliases?.some((a) => a.toLowerCase() === normalized)
  );
}
